{
  "identity": {
    "name": "MicroTech Systems",
    "location": "Boise, Idaho",
    "claims": [
      {
        "statement": "MicroTech Systems is located at 125 E 50th Street, Boise, ID 83714.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "Microtech Systems 125 E 50th Street , Boise, ID 83714 | 9AM - 5PM Monday-Friday"
      },
      {
        "statement": "The company also lists its address as Garden City, Idaho.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/contact-us",
        "quote": "125 E 50th St, Garden City, ID 83714"
      },
      {
        "statement": "MicroTech Systems was founded as a family business in 1970.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/en/about-microtech",
        "quote": "We started as a family business in 1970 – the year of the Apollo 13 space disaster; break-up of The Beatles"
      }
    ]
  },
  "industry": {
    "industry": "Managed IT Services & Cybersecurity",
    "activities": [
      "Managed IT Services",
      "24x7 Remote Monitoring",
      "Cybersecurity and Antivirus Solutions",
      "Cloud IT Services",
      "Microsoft 365 Migration and Management",
      "Windows Server Management"
    ],
    "claims": [
      {
        "statement": "MicroTech Systems operates as an IT support and managed IT service provider in Boise.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "As your dedicated IT support company in Boise, we provide ongoing Managed IT Services to ensure your business runs consistently and efficiently."
      },
      {
        "statement": "The company offers proprietary TechCare bundled IT support packages.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "TechCare™ is the proprietary IT support service offered by MicroTech in Boise."
      },
      {
        "statement": "MicroTech Systems is an information technology consulting and services firm rather than a trade contractor.",
        "label": "inference",
        "sourceUrl": "https://www.microtechboise.com/techcare",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://www.microtechboise.com/",
    "claims": [
      {
        "statement": "The company maintains its primary website at https://www.microtechboise.com/.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "Copyright © 2024 MicroTech Systems"
      },
      {
        "statement": "The firm operates Monday through Friday from 9:00 AM to 5:00 PM.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "Microtech Systems 125 E 50th Street , Boise, ID 83714 | 9AM - 5PM Monday-Friday"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "MicroTech Systems references technical certifications standard in the IT industry rather than trade contractor licensing.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/en/about-microtech",
        "quote": "We recognize that even high-quality products can become commodities and that certifications are near-standard practice."
      },
      {
        "statement": "No state contractor licenses for electrical, plumbing, or HVAC services are displayed on the website.",
        "label": "inference",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": null
      }
    ],
    "limitations": "Corporate business registration numbers with the Idaho Secretary of State and specific vendor technical certifications are not explicitly published on the public pages reviewed."
  },
  "existingSoftware": [
    {
      "product": "HubSpot",
      "purpose": "Content management system, web forms, and marketing tracking.",
      "evidence": {
        "statement": "The site loads HubSpot CMS tools, form handlers, and tracking scripts.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "Skip to content"
      }
    },
    {
      "product": "Google Tag Manager",
      "purpose": "Website analytics and tag container management.",
      "evidence": {
        "statement": "The site embeds Google Tag Manager containers.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/",
        "quote": "Skip to content"
      }
    },
    {
      "product": "JazzHR / applytojob.com",
      "purpose": "Applicant tracking system and careers portal embedding.",
      "evidence": {
        "statement": "The careers page embeds an applicant tracking frame hosted on microtechsystemsinc.applytojob.com.",
        "label": "fact",
        "sourceUrl": "https://www.microtechboise.com/about/careers",
        "quote": "CURRENT JOB OPENINGS"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The homepage contains unpopulated placeholder Latin dummy text.",
      "label": "fact",
      "sourceUrl": "https://www.microtechboise.com/",
      "quote": "Lorem ipsum dolor sit amet Lorem ipsum dolor sit amet, consectetur adipiscing elit. Id egestas nunc, habitasse ipsum."
    },
    {
      "statement": "The website content management template has unfinished display modules on the live homepage.",
      "label": "inference",
      "sourceUrl": "https://www.microtechboise.com/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Unedited placeholder template copy remains visible on the production homepage.",
      "label": "fact",
      "basis": "The live homepage displays multiple blocks of 'Lorem ipsum dolor sit amet' text."
    },
    {
      "problem": "Company is outside ForgeX's target market of trade contractors requiring field-service automation.",
      "label": "inference",
      "basis": "The company sells B2B IT support, cybersecurity, and cloud migration rather than residential HVAC, plumbing, or electrical work."
    }
  ],
  "existingSolutions": [
    {
      "solution": "HubSpot CMS Page Editor",
      "addresses": "Removing or editing unfinished placeholder Latin text blocks on the homepage.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX automation packages are recommended because MicroTech Systems is not within ForgeX's target industry segment."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "Custom AI agent workflows are not proposed for an IT service provider outside the target market."
  },
  "humanReview": [],
  "risks": [
    {
      "type": "operational",
      "description": "Offering trade contractor intake and dispatch automation to an IT MSP does not address their core commercial model."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": []
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner",
      "President",
      "Chief Executive Officer",
      "General Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://www.microtechboise.com/contact-us"
      },
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://www.microtechboise.com/contact-us"
      }
    ]
  },
  "discovery": {
    "questions": [],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://www.microtechboise.com/",
        "usedFor": "Business identification, services overview, location details, software script detection, and homepage content verification."
      },
      {
        "url": "https://www.microtechboise.com/en/about-microtech",
        "usedFor": "Company background, founding history, service philosophy, and certification statements."
      },
      {
        "url": "https://www.microtechboise.com/contact-us",
        "usedFor": "Contact telephone numbers, official email address, and secondary location naming."
      },
      {
        "url": "https://www.microtechboise.com/privacypolicy",
        "usedFor": "Corporate digital advertising privacy policy details and contact email confirmation."
      },
      {
        "url": "https://www.microtechboise.com/techcare",
        "usedFor": "Details regarding proprietary TechCare managed IT service offerings."
      },
      {
        "url": "https://www.microtechboise.com/about/careers",
        "usedFor": "Recruitment platform detection and verification of team leadership disclosure."
      }
    ],
    "limitations": [
      "No executive, owner, or manager names are presented in an official leadership directory on the site (names appear solely in third-party client testimonials, which cannot be cited per research guidelines).",
      "No pricing data for managed IT service packages is published on the website."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "MicroTech Systems is an IT managed service provider (MSP) offering computer networking, cloud solutions, and cybersecurity services in the Boise area. ForgeX's target profile consists specifically of owner-led home-service contractors (HVAC, plumbing, and electrical) managing trade job pipelines. Because the company operates entirely outside ForgeX's target industry segment, it is disqualified as not a fit."
  }
}
